import SwiftUIstruct GameDetailView: View {    let gameID: String    @StateObject private var viewModel = GameDetailViewModel()    var body: some View {        Group {            if viewModel.isLoading {                ProgressView("Loading...")                    .padding()            } else if let detail = viewModel.gameDetail {                ScrollView {                    VStack(spacing: 20) {                        AsyncImage(url: URL(string: detail.info.thumb)) { phase in                            if let image = phase.image {                                image                                    .resizable()                                    .aspectRatio(contentMode: .fit)                                    .cornerRadius(12)                                    .shadow(radius: 5)                            } else if phase.error != nil {                                Color.red.frame(height: 200)                            } else {                                ProgressView().frame(height: 200)                            }                        }                        .padding(.horizontal)                                                Text(detail.info.title)                            .font(.title)                            .fontWeight(.bold)                            .multilineTextAlignment(.center)                            .padding(.horizontal)                                                VStack(spacing: 5) {                            Text("Cheapest Price Ever: $\(detail.cheapestPriceEver.price)")                                .font(.headline)                            Text("Recorded on \(Date(timeIntervalSince1970: TimeInterval(detail.cheapestPriceEver.date)), formatter: dateFormatter)")                                .font(.caption)                                .foregroundColor(.secondary)                        }                                                Divider()                                                VStack(alignment: .leading, spacing: 10) {                            Text("Available Deals:")                                .font(.headline)                                .padding(.bottom, 5)                                                        ForEach(detail.deals) { deal in                                VStack(alignment: .leading) {                                    Text("StoreID: \(deal.storeID)")                                        .font(.subheadline)                                    HStack {                                        Text("Price: $\(deal.price)")                                        Text("Retail: $\(deal.retailPrice)")                                        Text("Savings: \(String(format: "%.0f", Double(deal.savings) ?? 0))%")                                            .foregroundColor(.green)                                    }                                    .font(.caption)                                }                                .padding(8)                                .background(Color.gray.opacity(0.1))                                .cornerRadius(8)                            }                        }                        .padding(.horizontal)                                                Spacer()                    }                    .padding(.top)                }                .navigationTitle(detail.info.title)                .navigationBarTitleDisplayMode(.inline)            } else if let errorMessage = viewModel.errorMessage {                Text(errorMessage)                    .foregroundColor(.red)                    .padding()            } else {                Text("No details available.")            }        }        .onAppear {            viewModel.fetchGameDetail(for: gameID)        }    }}// A helper date formatter for display.private let dateFormatter: DateFormatter = {    let formatter = DateFormatter()    formatter.dateStyle = .medium    formatter.timeStyle = .none    return formatter}()